            state
                .0
                .transcript_log
                .lock()
                .await
                .add(AGENT, &reply.text, reply.route.clone())
        {
            emit_json(state, json!({"type":"spoken", "entry":entry}));
        }
    }
    publish_status(state, status);
    drop(_transition);
    synthesize_reply_if_current(state, &reply.to_speak, generation).await
